import type { Enums, Insert, MaintenanceUpdate, Row, VehicleStatus } from '../src/types/database.maintenance';
const order: Insert<'maintenance_orders'> = {
  company_id: 'company', vehicle_id: 'vehicle', partner_id: 'partner',
  descricao_problema: 'Ruído no motor',
};
// Number is generated by the order trigger; its Insert optionality is tested below.
// @ts-expect-error unsupported status
const invalidStatus: Enums['order_status'] = 'Disponível';
// @ts-expect-error generated totals are not writable
const wrongTotal: Insert<'maintenance_orders'> = { ...order, valor_total: 100 };
// @ts-expect-error updates cannot change tenant identity
const moveTenant: MaintenanceUpdate<'maintenance_orders'> = { company_id: 'other' };
// @ts-expect-error timeline is append-only
const editTimeline: MaintenanceUpdate<'maintenance_order_timeline'> = {};
const status: VehicleStatus = 'Manutenção';
const visit: Pick<Row<'workshop_visits'>, 'downtime_horas'> = { downtime_horas: null };
const template: Insert<'maintenance_message_templates'> = { company_id: 'company', nome: 'Aviso', categoria: 'manutencao', conteudo: 'Olá, {PLACA}' };
void [order, invalidStatus, wrongTotal, moveTenant, editTimeline, status, visit, template];
